a=inc.index('        for (std::size_t i = 1;');b=inc.index('        if (consecutive)',a)
variants={'current':inc,'control':inc}
for w in [4,8,32]:
 block='''        std::size_t i = 1;
        for (; dense_size - i > WIDTH; i += WIDTH) {
            bool mismatch = false;
            for (std::size_t j = 0; j < WIDTH; ++j)
                mismatch |= static_cast<std::uintmax_t>(f[i + j].first) != i + j + 1;
            if (mismatch) { consecutive = false; break; }
        }
        for (; consecutive && i + 1 < dense_size; ++i) {
            if (static_cast<std::uintmax_t>(f[i].first) != i + 1) {
                consecutive = false; break;
            }
        }
'''.replace('WIDTH',str(w))
 variants['class'+str(w)]=inc[:a]+block+inc[b:]
for name,body in variants.items():
 (p/(name+'.inc')).write_text(body);(p/(name+'.hpp')).write_text(s.replace(inc,body,1));(p/(name+'_main.cpp')).write_text(sub.replace(inc,body,1))
