#include SOURCE
#include <chrono>
#include <cstdint>
#include <iostream>
#include <random>
#include <string>
#include <vector>
struct Mod{std::uint32_t v=0;Mod()=default;Mod(std::int64_t x):v(x%998244353){}Mod&operator+=(Mod b){v+=b.v;if(v>=998244353)v-=998244353;return *this;}Mod&operator-=(Mod b){if(v<b.v)v+=998244353;v-=b.v;return *this;}friend bool operator==(Mod,Mod)=default;};
int main(int argc,char**argv){if(argc!=4)return 1;const int n=std::stoi(argv[1]),shape=std::stoi(argv[2]),loops=std::stoi(argv[3]);IntegerSieve sieve(n);std::vector<std::pair<int,Mod>>a;if(shape<3 || shape==5){for(int i=1;i<=n;++i)a.emplace_back(i,Mod((i*13)%99));if(shape==1)std::reverse(a.begin(),a.end());else if(shape==2)std::shuffle(a.begin(),a.end(),std::mt19937(61022));else if(shape==5&&n>=3)std::swap(a[n-3],a[n-2]);}else{for(int i=1;i<=n;++i)if(n%i==0)a.emplace_back(i,Mod((i*13)%99));if(shape==4)std::reverse(a.begin(),a.end());}auto once=[&]{auto f=a;sparse_multiple_zeta_transform(f,sieve);sparse_multiple_mobius_transform(f,sieve);std::uint64_t sum=0;for(auto&[k,v]:f)sum+=v.v+k;return sum;};auto sum=once();auto start=std::chrono::steady_clock::now();for(int k=0;k<loops;++k)sum+=once();auto end=std::chrono::steady_clock::now();std::cout<<std::chrono::duration<double,std::milli>(end-start).count()<<' '<<sum<<'\n';}

