from pathlib import Path
import json,subprocess,statistics,hashlib,resource,fcntl
r=Path('/home/reinsirk/Atcoder_Env');p=Path(__file__).parent;vs=['current','control','class8','xor16','narrow16','div32'];fixtures=json.loads((r/'Audit/verify-zeta-sparse-ready-2026-10-24.json').read_text())['verification']['fixtures'];fixtures=[f for f in fixtures if f['name']in ['random_00.in','max_random_00.in','near_prime_00.in','near_prime_squared_00.in']];sha=lambda b:hashlib.sha256(b).hexdigest();d={'builds':[],'main':{}};modes={'gcc':['/usr/bin/g++'],'gcc_native':['/usr/bin/g++','-march=native'],'clang':['clang++','--gcc-install-dir=/usr/lib/gcc/x86_64-linux-gnu/15']}
for m,cc in modes.items():
 for v in vs:
  exe=p/(m+'_'+v);cmd=['taskset','-c','6',*cc,'-std=c++23','-O2','-Wall','-Wextra','-Werror','-pedantic-errors',str(p/(v+'_main.cpp')),'-o',str(exe)];q=subprocess.run(cmd,capture_output=True,text=True);assert q.returncode==0 and not q.stderr,(cmd,q.stderr);d['builds'].append(cmd)
 print('compiled',m,flush=True)
with open('/tmp/sirkit_performance_cpu14.lock','a')as a,open('/tmp/atcoder_full_performance_20261018/benchmark.lock','a')as b:
 fcntl.flock(a,fcntl.LOCK_EX);fcntl.flock(b,fcntl.LOCK_EX)
 for m in modes:
  d['main'][m]={}
  for f in fixtures:
   raw={v:[]for v in vs}
   for rep in range(11):
    for v in vs[rep%6:]+vs[:rep%6]:
     with open(f['input'],'rb')as inp:
      before=resource.getrusage(resource.RUSAGE_CHILDREN);q=subprocess.run(['taskset','-c','14',str(p/(m+'_'+v))],stdin=inp,capture_output=True);after=resource.getrusage(resource.RUSAGE_CHILDREN)
     assert q.returncode==0 and not q.stderr and sha(q.stdout)==f['output_sha256'];raw[v].append(1000*(after.ru_utime+after.ru_stime-before.ru_utime-before.ru_stime))
   med={v:statistics.median(xs)for v,xs in raw.items()};ratios={v:t/med['current']for v,t in med.items()};d['main'][m][f['name']]={'raw_cpu_ms':raw,'medians_cpu_ms':med,'ratios':ratios};print(m,f['name'],{v:round(x,3)for v,x in ratios.items()},flush=True)
